    @Override
    @NotNull
    public List<Player> getImportantMessageEntityPlayers()
    {
        final Set<Player> playerList = new HashSet<>(getMessagePlayerEntities());

        for (final ServerPlayer player : packageManager.getImportantColonyPlayers())
        {
