    }

    /**
     * Updates the citizen entities when needed and spawn the initial citizens on colony tick.
     *
     * @param colony the colony being ticked.
     */
    @Override
    public void onColonyTick(final IColony colony)
    {
        if (colony.getServerBuildingManager().hasTownHall() && (citizenRespawnTimer -= 500) < 0)
        {
            citizenRespawnTimer = 5 * 60 * TICKS_SECOND;
            getCitizens().stream().filter(Objects::nonNull).forEach(ICitizenData::updateEntityIfNecessary);
        }

        //  Spawn initial Citizens
        if (colony.getSettings().getSetting(BuildingTownHall.MOVE_IN).getValue() && colony.getServerBuildingManager().hasTownHall() && getCitizens().size() < MineColonies.getConfig().getServer().initialCitizenAmount.get())
        {
            respawnInterval -= 500 + (SECONDS_A_MINUTE * colony.getServerBuildingManager().getTownHall().getBuildingLevel());

            if (respawnInterval <= 0)
            {
                respawnInterval = 60 * TICKS_SECOND;
                int femaleCount = 0;
                for (ICitizenData citizens : getCitizens())
                {
                    femaleCount += citizens.isFemale() ? 1 : 0;
                }

                final boolean firstCitizen = getCitizens().size() == 0;
                final ICitizenData newCitizen = createAndRegisterCivilianData();
                if (firstCitizen)
                {
                    colony.getQuestManager().injectAvailableQuest(new QuestInstance(new ResourceLocation(MOD_ID, "tutorial/welcome"), colony, List.of(new CitizenTriggerReturnData(newCitizen))));
                }

                // For first citizen, give a random chance of male or female.
                if (getCitizens().size() == 1)
                {
                    newCitizen.setGenderAndGenerateName(random.nextBoolean());
                }
                // Otherwise, set the new colonist's gender to whatever gender is less common.
                // Use double division to avoid getting two male colonists in a row for the first set.
                else if (femaleCount < (getCitizens().size() - 1) / 2.0)
                {
                    newCitizen.setGenderAndGenerateName(true);
                }
                else
                {
                    newCitizen.setGenderAndGenerateName(false);
                }

                spawnOrCreateCivilian(newCitizen, colony.getWorld(), List.of(colony.getServerBuildingManager().getTownHall().getPosition()), true);

                IMinecoloniesAPI.getInstance().getEventBus().post(new CitizenAddedModEvent(newCitizen, CitizenAddedModEvent.CitizenAddedSource.INITIAL));
                colony.getEventDescriptionManager().addEventDescription(new CitizenSpawnedEvent(colony.getServerBuildingManager().getTownHall().getPosition(),
                      newCitizen.getName()));
            }
        }
    }

    @Override
    public void updateCitizenMourn(final ICitizenData data, final boolean mourn)
    {
        for (final ICitizenData citizen : getCitizens())
        {
            if (mourn)
            {
                if (!(citizen.getJob() instanceof AbstractJobGuard) && !(citizen.getJob() instanceof JobUndertaker) && (citizen.isRelatedTo(data) || citizen.doesLiveWith(data)))
                {
                    citizen.getCitizenMournHandler().addDeceasedCitizen(data.getName());
                }
            }
            else
            {
                citizen.getCitizenMournHandler().removeDeceasedCitizen(data.getName());
            }
            citizen.onDeath(data.getId());
        }
    }

    @Override
    public ICitizenData getRandomCitizen()
    {
        return (ICitizenData) citizens.values().toArray()[random.nextInt(citizens.values().size())];
    }

    @Override
    public void updateCitizenSleep(final boolean sleep)
    {
        this.areCitizensSleeping = sleep;
    }

    @Override
    public void onCitizenSleep()
    {
        for (final ICitizenData citizenData : citizens.values())
        {
            if (!(citizenData.isAsleep() || citizenData.getJob() instanceof AbstractJobGuard))
            {
                return;
            }
        }

        if (!this.areCitizensSleeping)
        {
            MessageUtils.format(ALL_CITIZENS_ARE_SLEEPING).sendTo(colony).forAllPlayers();
        }

        this.areCitizensSleeping = true;
    }

    @Override
    public void onWakeUp()
    {
        for (final ICitizenData citizenData : citizens.values())
        {
            citizenData.updateEntityIfNecessary();
            if (citizenData.getCitizenMournHandler().isMourning())
            {
                citizenData.getCitizenMournHandler().clearDeceasedCitizen();
                citizenData.getCitizenMournHandler().setMourning(false);
            }
            else
            {
                if (citizenData.getCitizenMournHandler().shouldMourn())
                {
                    citizenData.getCitizenMournHandler().setMourning(true);
                }
            }
        }
    }

    @Override
    public void afterBuildingLoad()
    {
        calculateMaxCitizens();

        for(final ICitizenData data: citizens.values())
        {
            data.onBuildingLoad();
        }
    }

    @Override
    public void onFlagChange()
    {
        for (ICitizenData citizen : this.getCitizens())
        {
            if (citizen.getEntity().isPresent() && citizen.getJob() instanceof IJobWithColonyFlag flagUser)
            {
                flagUser.onColonyFlagChanged();
            }
        }
    }
}

package com.minecolonies.core.colony.managers;

import com.minecolonies.api.MinecoloniesAPIProxy;
import com.minecolonies.api.advancements.AdvancementTriggers;
import com.minecolonies.api.colony.ICitizen;
import com.minecolonies.api.colony.ICitizenData;
import com.minecolonies.api.colony.ICivilianData;
import com.minecolonies.api.colony.IColony;
import com.minecolonies.api.colony.buildings.IBuilding;
import com.minecolonies.api.colony.managers.interfaces.IReproductionManager;
import com.minecolonies.api.util.BlockPosUtil;
import com.minecolonies.api.util.MessageUtils;
import com.minecolonies.core.colony.Colony;
import com.minecolonies.core.colony.buildings.modules.LivingBuildingModule;
import com.minecolonies.core.colony.buildings.workerbuildings.BuildingTownHall;
import com.minecolonies.core.colony.eventhooks.citizenEvents.CitizenBornEvent;
import com.minecolonies.core.util.AdvancementUtils;
import net.minecraft.core.BlockPos;
import org.jetbrains.annotations.NotNull;

import java.util.ArrayList;
import java.util.List;
import java.util.Random;

import static com.minecolonies.api.entity.ai.statemachine.tickratestatemachine.TickRateConstants.MAX_TICKRATE;
import static com.minecolonies.api.util.constant.StatisticsConstants.BIRTH;
import static com.minecolonies.api.util.constant.TranslationConstants.MESSAGE_NEW_CHILD_BORN;
import static com.minecolonies.core.colony.CitizenData.SUFFIXES;

/**
 * Repo manager to spawn children.
 */
public class ReproductionManager implements IReproductionManager
{
    /**
     * The time in seconds before the initial try to spawn. 5 minutes between each attempt.
     */
    private static final int MIN_TIME_BEFORE_SPAWNTRY = 20 * 60 * 5;

    /**
     * Interval at which the childen are created, in ticks. Every 10 min it tries to spawn a child.
     */
    private final static int CHILD_SPAWN_INTERVAL = 20 * 60 * 10;

    /**
     * Min necessary citizens for reproduction.
     */
    private static final int MIN_SIZE_FOR_REPRO   = 2;

    /**
     * The timer counting ticks to the next time creating a child
     */
    private int childCreationTimer;

    /**
     * The colony the manager belongs to.
     */
    private final Colony colony;

    /**
     * Random function for the manager to use.
     */
    private Random random = new Random();

    /**
     * Create a new reproduction manager.
     * @param colony the colony to spawn kids for.
     */
    public ReproductionManager(final Colony colony)
    {
        this.colony = colony;
        childCreationTimer = random.nextInt(CHILD_SPAWN_INTERVAL) + MIN_TIME_BEFORE_SPAWNTRY;
    }

    @Override
    public void onColonyTick(@NotNull final IColony colony)
    {
        if ( (childCreationTimer -= MAX_TICKRATE) <= 0)
        {
            childCreationTimer = (MIN_TIME_BEFORE_SPAWNTRY + random.nextInt(CHILD_SPAWN_INTERVAL)) * (colony.getCitizenManager().getCurrentCitizenCount() / Math.max(4, colony.getCitizenManager().getMaxCitizens()));
            trySpawnChild();
        }
    }

    /**
     * Try to spawn a new citizen as child. Mom / dad entities are required and chosen randomly in this hut. Childs inherit stats from their parents, avergaged +-2 Childs get
     * assigned to a free housing slot in the colony to be raised there, if the house has an adult living there the child takes its name and gets raised by it.
     */
    public void trySpawnChild()
    {
        // Spawn a child when adults are present
        if (colony.getSettings().getSetting(BuildingTownHall.MOVE_IN).getValue() && colony.getCitizenManager().getCurrentCitizenCount() < colony.getCitizenManager().getMaxCitizens() && colony.getCitizenManager().getCurrentCitizenCount() >= Math.min(MIN_SIZE_FOR_REPRO, MinecoloniesAPIProxy.getInstance().getConfig().getServer().initialCitizenAmount.get()))
        {
            if (!checkForBioParents())
            {
                return;
            }

            final IBuilding newHome = colony.getServerBuildingManager().getHouseWithSpareBed();
            if (newHome == null)
            {
                return;
            }

            final LivingBuildingModule module = newHome.getFirstModuleOccurance(LivingBuildingModule.class);
            final List<ICitizenData> assignedCitizens = module.getAssignedCitizen();
            assignedCitizens.removeIf(ICitizen::isChild);

            boolean isOnlyChildInColony = true;
            for (final ICitizenData data : colony.getCitizenManager().getCitizens())
            {
                if (data.isChild())
                {
                    isOnlyChildInColony = false;
                    break;
                }
            }

            final ICitizenData newCitizen = colony.getCitizenManager().createAndRegisterCivilianData();
            ICitizenData firstParent;
            ICitizenData secondParent;
            if (!assignedCitizens.isEmpty())
            {
                firstParent = assignedCitizens.get(random.nextInt(assignedCitizens.size()));
                secondParent = firstParent.getPartner();
                if (secondParent == null)
                {
                    assignedCitizens.removeIf(cit -> cit.getPartner() != null || cit.getName().equals(firstParent.getName()) || cit.isRelatedTo(firstParent) || cit.isChild());
                    if (assignedCitizens.size() > 0 && random.nextBoolean())
                    {
                        secondParent = assignedCitizens.get(random.nextInt(assignedCitizens.size()));
                    }
                    else
                    {
                        final BlockPos altPos = colony.getServerBuildingManager().getRandomBuilding(b -> b.hasModule(LivingBuildingModule.class) && !b.getPosition().equals(newHome.getPosition()) && BlockPosUtil.getDistance2D(b.getPosition(), newHome.getPosition()) < 50);
                        if (altPos != null)
                        {
                            final IBuilding building = colony.getServerBuildingManager().getBuilding(altPos);
                            final LivingBuildingModule altModule = building.getFirstModuleOccurance(LivingBuildingModule.class);

                            final List<ICitizenData> newAssignedCitizens = altModule.getAssignedCitizen();
                            newAssignedCitizens.removeIf(cit -> cit.isChild() || cit.getPartner() != null || cit.isRelatedTo(firstParent));
                            if (newAssignedCitizens.size() > 0)
                            {
                                secondParent = newAssignedCitizens.get(random.nextInt(newAssignedCitizens.size()));
                            }
                        }
                    }
                }
            }
            else
            {
                firstParent = null;
                secondParent = null;
            }

            if (secondParent != null)
            {
                firstParent.setPartner(secondParent.getId());
                secondParent.setPartner(firstParent.getId());
            }

            newCitizen.getCitizenSkillHandler().init(colony, firstParent, secondParent, random);
            newCitizen.setIsChild(true);

            final List<String> possibleSuffixes = new ArrayList<>();
            if (firstParent != null)
            {
                newCitizen.addSiblings(firstParent.getChildren().toArray(new Integer[0]));
                firstParent.addChildren(newCitizen.getId());
                possibleSuffixes.add(firstParent.getTextureSuffix());
            }

            if (secondParent != null)
            {
                newCitizen.addSiblings(secondParent.getChildren().toArray(new Integer[0]));
                secondParent.addChildren(newCitizen.getId());
                possibleSuffixes.add(secondParent.getTextureSuffix());
            }

            newCitizen.setParents(firstParent == null ? "" : firstParent.getName(), secondParent == null ? "" : secondParent.getName());
            newCitizen.generateName(random, firstParent == null ? "" : firstParent.getName(), secondParent == null ? "" : secondParent.getName(), colony.getCitizenNameFile());

            module.assignCitizen(newCitizen);

            for (final int sibling : newCitizen.getSiblings())
            {
                final ICitizenData siblingData = colony.getCitizenManager().getCivilian(sibling);
                if (siblingData != null)
                {
                    siblingData.addSiblings(newCitizen.getId());
                }
            }

            if (possibleSuffixes.contains("_w") && possibleSuffixes.contains("_d"))
            {
                possibleSuffixes.add("_b");
            }

            if (possibleSuffixes.isEmpty())
            {
                possibleSuffixes.addAll(SUFFIXES);
            }

            newCitizen.setSuffix(possibleSuffixes.get(random.nextInt(possibleSuffixes.size())));

            final int populationCount = colony.getCitizenManager().getCurrentCitizenCount();
            AdvancementUtils.TriggerAdvancementPlayersForColony(colony, playerMP -> AdvancementTriggers.COLONY_POPULATION.trigger(playerMP, populationCount));

            colony.getCitizenManager().spawnOrCreateCitizen(newCitizen, colony.getWorld(), newHome.getPosition());
            if (isOnlyChildInColony)
            {
                MessageUtils.format(MESSAGE_NEW_CHILD_BORN, newCitizen.getName(), colony.getName()).sendTo(colony).forManagers();
            }

            colony.getEventDescriptionManager().addEventDescription(new CitizenBornEvent(newHome.getPosition(), newCitizen.getName()));
            colony.getStatisticsManager().increment(BIRTH, colony.getDay());
        }
    }

    /**
     * Check if there are potential biological parents in the colony.
     * (At least one male/female citizen).
     * @return true if so.
     */
    private boolean checkForBioParents()
    {
        boolean hasMale = false;
        boolean hasFemale = false;

        for (final ICitizenData data : colony.getCitizenManager().getCitizens())
        {
            if (data.isFemale())
            {
                hasFemale = true;
            }
            else
            {
                hasMale = true;
            }

            if (hasFemale && hasMale)
            {
                return true;
            }
        }

        for (final ICivilianData data : colony.getVisitorManager().getCivilianDataMap().values())
        {
            if (data.isFemale())
            {
                hasFemale = true;
            }
            else
            {
                hasMale = true;
            }

            if (hasFemale && hasMale)
            {
                return true;
            }
        }
        return false;
    }
}

package com.minecolonies.core.colony.managers;

import com.google.common.collect.Maps;
import com.minecolonies.api.colony.ICitizenData;
import com.minecolonies.api.colony.IColony;
import com.minecolonies.api.colony.managers.interfaces.ITravellingManager;
import com.minecolonies.api.entity.citizen.AbstractEntityCitizen;
import com.minecolonies.api.util.EntityUtils;
import com.minecolonies.api.util.Log;
import com.minecolonies.api.util.constant.ColonyConstants;
import com.minecolonies.api.util.constant.NbtTagConstants;
import com.minecolonies.core.util.TeleportHelper;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.NbtUtils;
import net.minecraft.nbt.Tag;
import net.minecraftforge.common.util.INBTSerializable;

import java.util.Map;
import java.util.Optional;

/**
 * Implementation of the travelling system and its API.
 * Keeps track of the travelling destination and progress of a given party.
 * <p>
 * Does not handle any interactions with the entities or the citizens.
 * </p>
 */
public class TravellingManager implements ITravellingManager, INBTSerializable<CompoundTag>
{

    private final IColony                    colony;
    private final Map<Integer, TravelerData> travelerDataMap = Maps.newHashMap();

    public TravellingManager(final IColony colony) {this.colony = colony;}

    @Override
    public boolean isTravelling(final int citizenId)
    {
        return Optional.ofNullable(travelerDataMap.get(citizenId)).map(TravelerData::isTraveling).orElse(false);
    }

    @Override
    public Optional<BlockPos> getTravellingTargetFor(final int citizenId)
    {
        return Optional.ofNullable(travelerDataMap.get(citizenId)).map(TravelerData::getTarget);
    }

    @Override
    public void startTravellingTo(final int citizenId, final BlockPos target, final int travelTimeInTicks)
    {
        travelerDataMap.put(citizenId, new TravelerData(citizenId, target, travelTimeInTicks));
        colony.markDirty();
    }

    @Override
    public void finishTravellingFor(final int citizenId)
    {
        if (travelerDataMap.containsKey(citizenId))
        {
            travelerDataMap.remove(citizenId);
            colony.markDirty();
        }
    }

    @Override
    public void recallAllTravellingCitizens()
    {
        for (final Integer citizenId : travelerDataMap.keySet())
        {
            final ICitizenData citizenData = this.colony.getCitizenManager().getCivilian(citizenId);
            final BlockPos spawnHutPos;
            if (citizenData.getWorkBuilding() != null)
            {
                spawnHutPos = citizenData.getWorkBuilding().getPosition();
            }
            else
            {
                spawnHutPos = colony.getServerBuildingManager().getTownHall().getPosition();
            }

            Optional<AbstractEntityCitizen> optionalEntityCitizen = citizenData.getEntity();
            if (optionalEntityCitizen.isEmpty())
            {
                Log.getLogger().warn(String.format("The traveller %d from colony #%d has returned very confused!", citizenData.getId(), colony.getID()));
                citizenData.setNextRespawnPosition(EntityUtils.getSpawnPoint(colony.getWorld(), spawnHutPos));
                citizenData.updateEntityIfNecessary();
                optionalEntityCitizen = citizenData.getEntity();
            }

            optionalEntityCitizen.ifPresent(abstractEntityCitizen -> TeleportHelper.teleportCitizen(abstractEntityCitizen, colony.getWorld(), spawnHutPos));
        }

        this.travelerDataMap.clear();
        colony.markDirty();
    }

    public boolean onTick()
    {
        travelerDataMap.values().forEach(TravelerData::onTick);
        return true;
    }

    @Override
    public CompoundTag serializeNBT()
    {
        final CompoundTag data = new CompoundTag();
        final ListTag output = new ListTag();

        for (TravelerData travelerData : travelerDataMap.values())
        {
            CompoundTag serializeNBT = travelerData.serializeNBT();
            output.add(serializeNBT);
        }

        data.put(NbtTagConstants.TRAVELER_DATA, output);

        return data;
    }

    @Override
    public void deserializeNBT(final CompoundTag nbt)
    {
        final ListTag travelerData = nbt.getList(NbtTagConstants.TRAVELER_DATA, Tag.TAG_COMPOUND);
        travelerDataMap.clear();

        for (Tag travelerDatum : travelerData)
        {
            if (travelerDatum instanceof final CompoundTag compoundTag)
            {
                TravelerData data = new TravelerData(compoundTag);
                travelerDataMap.put(data.getCitizenId(), data);
            }
        }
    }

    private static final class TravelerData implements INBTSerializable<CompoundTag>
    {
        private int      citizenId           = -1;
        private BlockPos target              = BlockPos.ZERO;
        private int      initialTravelTime   = 0;
        private int      remainingTravelTime = 0;

        public TravelerData(final int citizenId, final BlockPos target, final int initialTravelTime)
        {
            this.citizenId = citizenId;
            this.target = target;
            this.initialTravelTime = initialTravelTime;
            this.remainingTravelTime = initialTravelTime;
        }

        public TravelerData(final CompoundTag tag)
        {
            this.deserializeNBT(tag);
        }

        public void onTick()
        {
            if (remainingTravelTime > 0)
            {
                remainingTravelTime -= ColonyConstants.UPDATE_TRAVELING_INTERVAL;
                remainingTravelTime = Math.max(0, remainingTravelTime);
            }
        }

        public boolean hasReachedTarget()
        {
            return remainingTravelTime == 0;
        }

        public double getTravelPercentage()
        {
            return ((double) remainingTravelTime * 100) / (double) initialTravelTime;
        }

        public int getCitizenId()
        {
            return citizenId;
        }

        public BlockPos getTarget()
        {
            return target;
        }

        public int getInitialTravelTime()
        {
            return initialTravelTime;
        }

        public int getRemainingTravelTime()
        {
            return remainingTravelTime;
        }

        public boolean isTraveling()
        {
            return !hasReachedTarget();
        }

        @Override
        public CompoundTag serializeNBT()
        {
            final CompoundTag data = new CompoundTag();
            data.putInt(NbtTagConstants.TAG_CITIZEN, citizenId);
            data.put(NbtTagConstants.TAG_TARGET, NbtUtils.writeBlockPos(target));
            data.putInt(NbtTagConstants.TAG_INITIAL_TRAVEL_TIME, initialTravelTime);
            data.putInt(NbtTagConstants.TAG_REMAINING_TRAVEL_TIME, remainingTravelTime);
            return data;
        }

        @Override
        public void deserializeNBT(final CompoundTag nbt)
        {
            this.citizenId = nbt.getInt(NbtTagConstants.TAG_CITIZEN);
            this.target = NbtUtils.readBlockPos(nbt.getCompound(NbtTagConstants.TAG_TARGET));
            this.initialTravelTime = nbt.getInt(NbtTagConstants.TAG_INITIAL_TRAVEL_TIME);
            this.remainingTravelTime = nbt.getInt(NbtTagConstants.TAG_REMAINING_TRAVEL_TIME);
        }
    }
}

